from pathlib import Path
import base64, gzip, re

ROOT = Path('buildsrc/quiet-diary')
FILES = {
'app/src/main/res/layout/activity_dream_hub.xml': '',
'app/src/main/res/layout/activity_morning.xml': '',
'app/src/main/res/layout/activity_night_program.xml': '',
'app/src/main/res/layout/activity_sound_library.xml': ''
}

for rel, payload in FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

gradle = ROOT / 'app/build.gradle.kts'
text = gradle.read_text(encoding='utf-8')
text = re.sub(r'versionCode\s*=\s*\d+', 'versionCode = 30040', text)
text = re.sub(r'versionName\s*=\s*"[^"]+"', 'versionName = "0.30.4"', text)
gradle.write_text(text, encoding='utf-8')
print('Somnori 0.30.4 Showcase Polish applied')
